# -*- coding: utf-8 -*-
import json
import re
from pathlib import Path
from shortcuts import render_shortcuts

# Each entry mirrors one section in public/help.html; technical examples remain in the original HTML.
content = {
'zh-CN': [
('入门', '''<p>DBDock 是一款 macOS 桌面数据库客户端，支持 MySQL、PostgreSQL、SQLite、Redis、MongoDB 和 Cloudflare D1。它将连接管理、SSH 隧道和数据库工具集中在一起，并支持 Vim、浅色与深色主题及多种语言。</p><p>按 ⌘N 新建连接，选择数据库类型，填写主机、用户名和密码后点击“测试”。也可以按 ⌘O 导入 TablePlus、DBeaver、URL 或 DBDock 导出文件。</p><p>双击连接卡片或点击“连接”打开会话；⌃1 返回连接列表。密码保存在 macOS 钥匙串中，表单不会显示已保存的密码。</p>'''),
('连接与分组', '''<h3>分组和多选</h3><p>使用侧边栏创建、重命名、移动或删除分组。路径中的 <code> / </code> 表示嵌套；删除分组时选择连接的新位置，数据库内容不会删除。将鼠标移到卡片上，把替代数据库图标的手柄拖到左侧分组；目标会高亮。也可使用“移动到分组”。</p><p>点击卡片或右上角的选择标记可选中或取消选中，支持多选。底部选择栏支持批量移动、导出和删除；空间不足时可横向滚动。Esc 或“清除选择”取消选择。</p><p>连接编辑窗口中的表单可滚动，“测试”“取消”和“保存”按钮固定在底部。</p><h3>环境标签</h3><p>连接可标记为本地、开发、测试、预发布或生产，并按标签筛选。表单中的环境选项用对应颜色显示边框和文字，选中项使用实色背景。生产连接和会话标签有红色标识。</p><h3>连接健康检查</h3><p>点击“批量检查当前列表”，或选择卡片后点击“检查已选”。窗口会检查必填项；点击“批量测试”后，最多同时测试 4 个配置完整的连接，可能需要钥匙串授权。停止会取消等待中的检查，已开始的检查会继续完成。</p><p>窗口显示成功或失败原因，卡片以绿色对勾或红色警告图标及简短时间显示上次结果；悬停可查看完整状态和时间。未进行测试时可在窗口中编辑或删除连接。取消编辑会保留结果；保存后仅清除该连接的旧结果，可重新测试。SQLite 文件不存在时会提示，不会创建文件。</p>'''),
('导入与导出', '''<p>“文件 → 导入”（⌘O）自动识别 DBDock JSON、TablePlus Connections.plist、DBeaver data-sources.json 和含 URL 的文本或 .env。TablePlus 和 DBeaver 的密码不能读取，请导入后填写；URL 中的密码保存到钥匙串。同一来源再次导入会更新已有连接。⇧⌘I 可粘贴 URL。<code>rediss://</code> 暂不支持。</p><h3>导出</h3><p>“文件 → 导出”（⇧⌘E）可导出全部或所选连接。包含密码时，设置口令可使用 AES-256-GCM 加密，密钥由 Argon2id 派生。不设置口令时密码为明文，请妥善保管。</p>'''),
('SSH 隧道', '''<p>在连接表单启用“通过 SSH”。数据库主机和端口从 SSH 服务器访问：同机数据库可用 127.0.0.1，也可填写私有 RDS 地址。</p><p>支持 ssh-agent、~/.ssh/config 中的 IdentityFile、默认密钥、指定密钥文件和密码。主机密钥必须已在 ~/.ssh/known_hosts 中验证；请先通过 OpenSSH 确认新主机。未知、已更改、不可读取的密钥和主机证书会被拒绝。</p><p>Server 可填写 SSH 配置别名。DBDock 隧道暂不支持 ProxyJump，请直接连接最后一跳。</p>'''),
('SSH 主机配置', '''<p>“文件 → SSH 主机”（⇧⌘H）管理 ~/.ssh/config。可增删主机，编辑 HostName、User、Port、IdentityFile 和 ProxyJump，并用代理或密钥测试登录。选择终端或 iTerm2 后点击“连接”，可使用 OpenSSH 打开已保存的主机；修改后请先保存。</p><p>其他配置、注释和缩进会保留；原始文件编辑器支持 Host *、Match 等配置。每次保存前会创建带时间戳的 config.dbdock-*.bak。主机旁的数字表示使用它的 DBDock 连接数量。</p>'''),
('SQL 数据库', '''<h3>快速切换</h3><p>按 ⌘K 搜索已保存的连接、当前会话可用的数据库和架构，以及侧栏当前架构中的表。选中一项后可收藏，或通过「最近访问」返回之前打开的项目。收藏和最近访问保存在本机。切换 MySQL 或 PostgreSQL 数据库时会打开或复用独立会话。</p><h3>浏览与查询</h3><p>选择数据库或 schema，再打开表。数据视图默认每页加载 5 行，可调整每页数量；支持 WHERE 过滤、列名补全和排序；结构视图列出字段、类型、默认值和主键。</p><p>SQL 编辑器按 ⌘↵ 执行选区或光标所在的完整语句，⇧⌘↵ 执行全部脚本；支持多条语句、表和列补全。可在工具栏保存或载入 SQL 文件。打开「查询历史」搜索、预览并载入本次运行中提交的 SQL。历史按连接和打开会话时的数据库保存，退出应用后清除。⌃1–9 切换顶部标签，⌘1–9 切换数据库标签，按住对应按键显示数字；⌥⌘←/→ 与 ⌃⇧Tab / ⌃Tab 可循环切换。MySQL 与 PostgreSQL 可取消查询；SQLite 与 D1 不支持。SQL 编辑器使用一个连接，USE、SET 和事务作用于该会话。MySQL 和 PostgreSQL 的表格浏览使用独立连接，只显示已提交的数据；编辑器的会话设置和临时表不会共享。</p><h3>SQL 补全</h3><p>在 FROM 或 JOIN 后按空格可查看表、视图和 CTE。不带 schema 的表名按编辑器连接当前的搜索路径或数据库解析，包括 SET search_path 或 USE 的变更。输入 schema. 可查看其他 schema 的表，输入别名和点号可查看对应字段，包括 CTE 和子查询输出的列。为计算表达式添加别名后，可在外层查询中引用。WHERE 和 UPDATE … SET 后会根据当前查询的作用域与已知字段类型提示。按 Tab 接受补全。</p><p>在 JOIN … ON 后按空格，会根据表之间声明的外键提示关联条件，复合外键会插入全部列对。PostgreSQL 和 MySQL 的 ENUM 列支持在比较、IN 列表和 UPDATE … SET 赋值时提示已声明的值。</p><h3>编辑数据</h3><p>有主键的表支持双击编辑、添加或删除行、设置 NULL。⌘S 提交，预览 SQL 可查看将执行的语句。所有操作在一个事务中提交；任何 UPDATE 或 DELETE 未恰好匹配一行时全部回滚。</p><h3>D1 与兼容服务</h3><p>D1 需要账户 ID、数据库 ID 和具备 D1 Edit 权限的 API 令牌，通过 Cloudflare REST API 访问；网格编辑作为一次原子请求提交。StarRocks 和 Doris 可使用 MySQL 类型。</p><h3>筛选、导出与保护</h3><p>点击“筛选”组合多个字段条件，可匹配全部（AND）或任一（OR）。“索引”和“外键”用于查看元数据。查询结果栏可将当前结果导出为 CSV 或 JSON，导出范围与当前显示的结果一致。JSON 保留列顺序、重复列名和 NULL。CSV 会为可能被电子表格识别为公式的文本加前缀。</p><p>生产 SQL 连接可直接执行常规只读查询。写入、加锁或无法确定影响的 SQL，以及表格提交，仍需确认。在连接设置也可开启确认或选择“仅浏览”，后者禁用编辑器执行和表格提交。受保护的连接使用可视化筛选。修改设置后请重新连接。更新或删除会验证加载时的行版本，发生冲突时回滚整批并保留待提交修改。点击“放弃修改并重新加载”可查看最新值。</p><h3>结构编辑和表数据文件</h3><p>选择 schema 后点击“新建表”，填写列名、类型、默认值和主键，预览 SQL 再应用。已有表可从“结构 → 编辑结构”添加、重命名或删除列，删除需单独确认。PostgreSQL 还可更改已有列的类型和 NULL 约束，PostgreSQL 和 MySQL 可更改已有默认值。</p><p>在数据标签页导入 CSV 或 JSON，可先预览和映射列。导入会追加数据，失败时回滚整批。CSV 需要 UTF-8 表头，未加引号的空字段视为 NULL，加引号的空值视为空字符串。JSON 支持对象数组或 DBDock 的 columns/rows 格式。每次最多 5 MiB、5,000 行，D1 的生成 SQL 另有 90 KB 限制。</p><p>数据标签页的导出写出整表或视图，不套用筛选或待提交修改。D1 最多导出 5,000 行。二进制列用 0x 开头的十六进制表示。需要保留数据原值用于重新导入时，建议使用 JSON。</p>'''),
('Redis', '''<p>使用 SCAN 和匹配模式浏览键，点击“加载更多”继续。选择键可查看 string、hash、list、set、zset 或 stream 的预览、TTL 和大小；JSON 字符串会格式化显示。</p><p>通过数据库下拉框或 SELECT 切换数据库；底部控制台执行命令，↑ / ↓ 浏览历史。删除键前会确认。</p>'''),
('MongoDB', '''<p>使用主机和端口，或在主机中输入 mongodb:// / mongodb+srv:// URI。选项支持 authSource、tls 等；SSH 连接需要分别填写主机和端口。</p><h3>集合</h3><p>选择集合后可使用宽松语法填写 filter、sort 和 projection，支持 ObjectId 和 ISODate。切换表格或 JSON，双击文档编辑 Extended JSON，或插入和删除；已有文档的 _id 不可更改。可查看索引。</p><h3>Shell</h3><p>⌘↵ 执行当前行或选中内容。支持 find、aggregate、countDocuments、distinct、插入、更新、删除、db.runCommand、show dbs、show collections 和 use。</p>'''),
('Vim 模式与外观', '''<p>在“设置”（⌘,）中选择浅色、深色或跟随系统；语言可选择跟随系统、英文、简体中文、繁体中文和日语。Vim 模式适用于 SQL 编辑器、Mongo Shell、文档及 SSH 配置编辑器。</p><p>Esc 退出插入模式并关闭补全；:w 在文档和配置编辑器中保存，在 SQL 编辑器和 Shell 中运行。编辑器中的 Esc 不会关闭对话框。</p>'''),
('键盘快捷键', ''),
('数据保存位置', '''<p>连接和分组：<code>~/Library/Application Support/xyz.phpz.app.dbdock/</code>。密码、API 令牌及 SSH 口令：macOS 钥匙串服务 <code>xyz.phpz.app.dbdock</code>。SSH 主机：<code>~/.ssh/config</code>。界面设置保存在应用中。</p><p>应用只连接用户指定的数据库和 SSH 服务器；D1 还会访问 Cloudflare API。</p>'''),
('故障排查', '''<h3>钥匙串反复请求授权</h3><p>更新后首次读取时，macOS 可能要求授权旧钥匙串条目，以便 DBDock 复制凭据库。旧条目保留作恢复副本，之后不会同步更新。后续请使用同一签名身份的已安装应用；更换或丢失签名身份可能需要重新授权。</p><h3>导入后密码认证失败</h3><p>TablePlus 和 DBeaver 不提供密码，请编辑连接并输入密码。</p><h3>SSH 主机密钥被拒绝</h3><p>确认主机密钥是否可信；首次连接先使用 OpenSSH 验证。如果服务器重建导致密钥变化，核实后用 ssh-keygen -R host 移除旧记录，再使用 OpenSSH 验证新密钥。</p><h3>MySQL 兼容服务无法连接</h3><p>检查端口和用户来源权限。StarRocks / Doris 通常使用 9030。</p><h3>表只读</h3><p>网格编辑需要主键，视图始终只读；可使用 SQL 编辑器。</p>''')],
'zh-TW': [
('入門', '''<p>DBDock 是一款 macOS 桌面資料庫用戶端，支援 MySQL、PostgreSQL、SQLite、Redis、MongoDB 和 Cloudflare D1。它整合連線管理、SSH 通道及資料庫工具，並支援 Vim、淺色與深色主題和多種語言。</p><p>按 ⌘N 新增連線，選擇資料庫類型，填寫主機、使用者名稱與密碼後按「測試」。也可按 ⌘O 匯入 TablePlus、DBeaver、URL 或 DBDock 匯出檔。</p><p>按兩下連線卡片或按「連線」開啟工作階段；⌃1 返回連線清單。密碼儲存在 macOS 鑰匙圈中，表單不會顯示已儲存的密碼。</p>'''),
('連線與群組', '''<h3>群組與多選</h3><p>在側邊欄建立、重新命名、移動或刪除群組。路徑中的 <code> / </code> 表示巢狀結構；刪除時選擇連線的新位置，不會刪除資料庫內容。將滑鼠移至卡片，把取代資料庫圖示的把手拖到左側群組；目標會反白。也可使用「移至群組」。</p><p>點擊卡片或右上角的選取標記，可選取或取消選取，並支援多選。底部選取列支援批次移動、匯出及刪除；空間不足時可水平捲動。Esc 或「清除選取」取消選取。</p><p>連線編輯視窗中的表單可捲動，「測試」「取消」和「儲存」按鈕固定在底部。</p><h3>環境標籤</h3><p>可標記本機、開發、測試、預發布或正式環境，並依標籤篩選。表單中的環境選項以對應顏色顯示邊框和文字，選取的項目使用實色背景。正式環境連線及工作階段有紅色標示。</p><h3>連線健康檢查</h3><p>按「批次檢查目前清單」，或選取卡片後按「檢查已選」。視窗會檢查必填項目；按「批次測試」後，最多同時測試 4 個設定完整的連線，可能需要鑰匙圈授權。停止會取消等待中的檢查，已開始的檢查會繼續完成。</p><p>視窗顯示成功或失敗原因，卡片以綠色勾號或紅色警告圖示及簡短時間顯示上次結果；將滑鼠移至圖示可查看完整狀態和時間。未進行測試時可在視窗中編輯或刪除連線。取消編輯會保留結果；儲存後只清除該連線的舊結果，可重新測試。SQLite 檔案不存在時會顯示提示，不會建立檔案。</p>'''),
('匯入與匯出', '''<p>「檔案 → 匯入」（⌘O）自動辨識 DBDock JSON、TablePlus Connections.plist、DBeaver data-sources.json 及含 URL 的文字或 .env。TablePlus 和 DBeaver 的密碼無法讀取，請匯入後填寫；URL 密碼儲存至鑰匙圈。再次匯入同一來源會更新現有連線。⇧⌘I 可貼上 URL。<code>rediss://</code> 暫不支援。</p><h3>匯出</h3><p>「檔案 → 匯出」（⇧⌘E）可匯出全部或選取的連線。包含密碼時，設定密語可使用 AES-256-GCM 加密，金鑰由 Argon2id 衍生。不設定密語時密碼為明文，請妥善保管。</p>'''),
('SSH 通道', '''<p>在連線表單啟用「透過 SSH」。資料庫主機和連接埠從 SSH 伺服器存取：同一台主機上的資料庫可用 127.0.0.1，也可填寫私有 RDS 位址。</p><p>支援 ssh-agent、~/.ssh/config 的 IdentityFile、預設金鑰、指定金鑰檔及密碼。主機金鑰必須已在 ~/.ssh/known_hosts 中驗證；請先透過 OpenSSH 確認新主機。未知、已變更、無法讀取的金鑰及主機憑證會被拒絕。</p><p>Server 可填入 SSH 設定別名。DBDock 通道尚不支援 ProxyJump，請直接連接最後一跳。</p>'''),
('SSH 主機設定', '''<p>「檔案 → SSH 主機」（⇧⌘H）管理 ~/.ssh/config。可新增或刪除主機，編輯 HostName、User、Port、IdentityFile、ProxyJump，並以代理程式或金鑰測試登入。選擇終端機或 iTerm2 後按「連線」，即可使用 OpenSSH 開啟已儲存的主機；修改後請先儲存。</p><p>其他設定、註解及縮排會保留；原始檔案編輯器支援 Host *、Match 等設定。每次儲存前會建立帶時間戳記的 config.dbdock-*.bak。主機旁的數字代表使用它的 DBDock 連線數量。</p>'''),
('SQL 資料庫', '''<h3>快速切換</h3><p>按 ⌘K 搜尋已儲存的連線、目前可使用的資料庫和結構描述，以及側邊欄目前結構描述中的資料表。選取項目後可加入收藏，也可以透過「最近存取」返回曾開啟的項目。收藏和最近存取儲存在本機。切換 MySQL 或 PostgreSQL 資料庫會開啟或重用獨立的工作階段。</p><h3>瀏覽與查詢</h3><p>選擇資料庫或 schema，再開啟資料表。資料檢視預設每頁載入 5 列，可調整每頁數量；支援 WHERE 篩選、欄位補全及排序；結構檢視列出欄位、類型、預設值與主鍵。</p><p>SQL 編輯器按 ⌘↵ 執行選取內容或游標所在的完整陳述式，⇧⌘↵ 執行全部腳本；支援多個敘述及資料表、欄位補全。可在工具列儲存或載入 SQL 檔案。開啟「查詢記錄」搜尋、預覽並載入本次執行期間提交的 SQL。記錄依連線及開啟工作階段時的資料庫儲存，結束應用程式後清除。⌃1–9 切換頂部分頁，⌘1–9 切換資料庫分頁，按住對應按鍵顯示數字；⌥⌘←/→ 與 ⌃⇧Tab / ⌃Tab 可循環切換。MySQL 和 PostgreSQL 可取消查詢，SQLite 和 D1 不支援。SQL 編輯器使用一個連線，USE、SET 和交易在該工作階段生效。MySQL 和 PostgreSQL 的資料表瀏覽使用獨立連線，只顯示已提交的資料；編輯器的工作階段設定與暫存表不會共用。</p><h3>SQL 補全</h3><p>在 FROM 或 JOIN 後按空格可查看資料表、檢視表和 CTE。未指定 schema 的名稱依編輯器連線目前的搜尋路徑或資料庫解析，包括 SET search_path 或 USE 的變更。輸入 schema. 可查看其他 schema 的資料表，輸入別名和點號可查看對應欄位，包括 CTE 和子查詢輸出的欄位。為運算式加上別名，即可在外層查詢中參照。WHERE 和 UPDATE … SET 後會依目前查詢的範圍及已知欄位型別提示。按 Tab 接受補全。</p><p>在 JOIN … ON 後按空格，會依資料表之間宣告的外鍵提示關聯條件，複合外鍵會插入所有欄位配對。PostgreSQL 和 MySQL 的 ENUM 欄位支援在比較、IN 清單和 UPDATE … SET 指派時提示已宣告的值。</p><h3>編輯資料</h3><p>有主鍵的資料表支援按兩下編輯、新增或刪除列、設定 NULL。⌘S 提交；預覽 SQL 可查看將執行的敘述。所有操作在單一交易中提交；任何 UPDATE 或 DELETE 未恰好符合一列時全部回滾。</p><h3>D1 與相容服務</h3><p>D1 需要帳戶 ID、資料庫 ID 和具有 D1 Edit 權限的 API 權杖，透過 Cloudflare REST API 存取；表格編輯以單次原子請求提交。StarRocks 和 Doris 可使用 MySQL 類型。</p><h3>篩選、匯出與保護</h3><p>按「篩選」組合多個欄位條件，可符合全部（AND）或任一（OR）。「索引」和「外鍵」可查看中繼資料。查詢結果列可將目前結果匯出為 CSV 或 JSON，匯出範圍與目前顯示的結果一致。JSON 保留欄位順序、重複欄名和 NULL。CSV 會為可能被試算表視為公式的文字加上前綴。</p><p>正式 SQL 連線可直接執行一般唯讀查詢。寫入、鎖定或影響不明的 SQL，以及資料表提交，仍需確認。連線設定也可開啟確認或選擇「僅瀏覽」，後者會停用編輯器執行及資料表提交。受保護的連線請使用視覺化篩選。變更設定後請重新連線。更新或刪除時會檢查載入時的列版本，發生衝突會回復整批並保留待提交變更。按「捨棄變更並重新載入」可查看最新值。</p><h3>結構編輯與資料表檔案</h3><p>選擇 schema 後按「新增資料表」，輸入欄位名稱、型別、預設值和主鍵，再預覽並套用 SQL。現有資料表可用「結構 → 編輯結構」新增、重新命名或刪除欄位，刪除需要另外確認。PostgreSQL 也能變更型別和 NULL 限制，PostgreSQL 和 MySQL 可變更現有預設值。</p><p>在資料分頁匯入 CSV 或 JSON，可預覽並對應欄位。匯入會附加資料，失敗時回復整批。CSV 需要 UTF-8 標題列，未加引號的空欄位視為 NULL，加引號的空值視為空字串。JSON 支援物件陣列或 DBDock 的 columns/rows 格式。每次上限為 5 MiB、5,000 列，D1 產生的 SQL 另有 90 KB 上限。</p><p>資料分頁可匯出整張資料表或檢視表，匯出時不套用篩選或待提交變更。D1 最多匯出 5,000 列。二進位欄位用 0x 開頭的十六進位表示。需要保留原值再匯入時，建議使用 JSON。</p>'''),
('Redis', '''<p>使用 SCAN 和比對模式瀏覽鍵，按「載入更多」繼續。選取鍵可檢視 string、hash、list、set、zset 或 stream 的預覽、TTL 和大小；JSON 字串會格式化顯示。</p><p>透過資料庫下拉選單或 SELECT 切換資料庫；底部主控台執行命令，↑ / ↓ 瀏覽歷史。刪除鍵前會要求確認。</p>'''),
('MongoDB', '''<p>使用主機與連接埠，或在主機中輸入 mongodb:// / mongodb+srv:// URI。選項支援 authSource、tls 等；SSH 連線需要分別填寫主機和連接埠。</p><h3>集合</h3><p>選擇集合後可使用寬鬆語法填寫 filter、sort 和 projection，支援 ObjectId 和 ISODate。切換表格或 JSON，按兩下文件編輯 Extended JSON，或新增和刪除；現有文件的 _id 不可更改。可查看索引。</p><h3>Shell</h3><p>⌘↵ 執行目前行或選取內容。支援 find、aggregate、countDocuments、distinct、插入、更新、刪除、db.runCommand、show dbs、show collections 和 use。</p>'''),
('Vim 模式與外觀', '''<p>在「設定」（⌘,）中選擇淺色、深色或跟隨系統；語言可選跟隨系統、英文、簡體中文、繁體中文和日文。Vim 模式適用於 SQL 編輯器、Mongo Shell、文件與 SSH 設定編輯器。</p><p>Esc 離開插入模式並關閉補全；:w 在文件和設定編輯器中儲存，在 SQL 編輯器和 Shell 中執行。編輯器中的 Esc 不會關閉對話框。</p>'''),
('鍵盤快捷鍵', ''),
('資料儲存位置', '''<p>連線與群組：<code>~/Library/Application Support/xyz.phpz.app.dbdock/</code>。密碼、API 權杖與 SSH 密語：macOS 鑰匙圈服務 <code>xyz.phpz.app.dbdock</code>。SSH 主機：<code>~/.ssh/config</code>。介面設定儲存於應用程式中。</p><p>應用程式只連線至使用者指定的資料庫和 SSH 伺服器；D1 亦會存取 Cloudflare API。</p>'''),
('疑難排解', '''<h3>鑰匙圈反覆要求授權</h3><p>更新後首次讀取時，macOS 可能要求授權舊鑰匙圈項目，以便 DBDock 複製憑證庫。舊項目保留作還原副本，之後不會同步更新。後續請使用相同簽署身分的已安裝應用程式；更換或遺失身分可能需要重新授權。</p><h3>匯入後密碼驗證失敗</h3><p>TablePlus 和 DBeaver 不提供密碼，請編輯連線並輸入密碼。</p><h3>SSH 主機金鑰被拒絕</h3><p>確認主機金鑰是否可信；首次連線先透過 OpenSSH 驗證。若伺服器重建導致金鑰變更，確認後用 ssh-keygen -R host 移除舊紀錄，再以 OpenSSH 驗證新金鑰。</p><h3>MySQL 相容服務無法連線</h3><p>檢查連接埠和使用者來源權限。StarRocks / Doris 通常使用 9030。</p><h3>資料表唯讀</h3><p>表格編輯需要主鍵，檢視表一律唯讀；可使用 SQL 編輯器。</p>''')],
'ja': [
('はじめに', '''<p>DBDock は MySQL、PostgreSQL、SQLite、Redis、MongoDB、Cloudflare D1 に対応した macOS デスクトップクライアントです。接続管理、SSH トンネル、データベースツールをひとつにまとめ、Vim、ライト・ダークテーマ、複数言語に対応しています。</p><p>⌘N で接続を作成し、データベースの種類、ホスト、ユーザー名、パスワードを入力して「テスト」を押します。⌘O で TablePlus、DBeaver、URL、DBDock のエクスポートもインポートできます。</p><p>接続カードをダブルクリックするか「接続」を押してセッションを開きます。⌃1 で接続一覧に戻ります。パスワードは macOS キーチェーンに保存され、入力欄には表示されません。</p>'''),
('接続とグループ', '''<h3>グループと複数選択</h3><p>サイドバーでグループの作成、名前変更、移動、削除ができます。パスの <code> / </code> で階層化します。削除時には接続の移動先を選択し、データベースの内容は削除されません。カードにマウスを重ね、データベースのアイコンに代わって表示されるハンドルを左側のグループへドラッグします。移動先は強調表示されます。「グループに移動」も使えます。</p><p>カードまたは右上のマークをクリックすると選択・解除でき、複数選択にも対応します。画面下の選択バーから一括移動、エクスポート、削除ができます。幅が足りない場合はバーを横にスクロールできます。Esc または「選択を解除」で解除します。</p><p>接続編集画面ではフォームをスクロールでき、「テスト」「キャンセル」「保存」は画面下に固定されます。</p><h3>環境タグ</h3><p>ローカル、開発、テスト、ステージング、本番のタグを付けて絞り込めます。フォームの環境選択肢は枠と文字に各環境の色を使い、選択中の項目は背景を塗りつぶします。本番の接続とセッションは赤く表示されます。</p><h3>接続のヘルスチェック</h3><p>「表示中を一括チェック」を押すか、カードを選択して選択件数のチェックボタンを押します。画面で必須項目を確認し、一括テストで設定が揃った接続を最大 4 件同時にテストします。キーチェーンへのアクセスを求める場合があります。停止すると待機中のチェックを取り消し、実行中のチェックは完了まで続きます。</p><p>画面に成功またはエラーが表示され、カードには緑のチェックまたは赤の警告アイコンと短い時刻で前回の結果が表示されます。マウスを重ねると完全な状態と時刻を確認できます。テスト中以外は画面から接続の編集や削除ができます。編集をキャンセルすると結果は保持され、保存するとその接続の結果だけが消去され、再テストできます。存在しない SQLite ファイルは作成せず、エラーを表示します。</p>'''),
('インポートとエクスポート', '''<p>「ファイル → インポート」（⌘O）は DBDock JSON、TablePlus Connections.plist、DBeaver data-sources.json、URL を含むテキストや .env を自動判別します。TablePlus と DBeaver のパスワードは読み取れないため、インポート後に入力してください。URL のパスワードはキーチェーンに保存され、同じ接続の再インポートは既存の接続を更新します。⇧⌘I で URL を貼り付けられます。<code>rediss://</code> は未対応です。</p><h3>エクスポート</h3><p>「ファイル → エクスポート」（⇧⌘E）で全件または選択した接続を書き出します。パスワードを含める場合、パスフレーズを設定すると AES-256-GCM で暗号化し、Argon2id で鍵を導出します。パスフレーズがない場合は平文のため、安全に保管してください。</p>'''),
('SSH トンネル', '''<p>接続フォームで「SSH 経由」を有効にします。データベースのホストとポートは SSH サーバー側から接続します。同じマシンのデータベースには 127.0.0.1、RDS にはプライベートアドレスを指定できます。</p><p>ssh-agent、~/.ssh/config の IdentityFile、既定の鍵、指定した鍵ファイル、パスワードに対応します。ホスト鍵は事前に ~/.ssh/known_hosts で信頼されている必要があります。新しいホストは OpenSSH で確認してください。未知、変更済み、読み取れない鍵とホスト証明書は拒否されます。</p><p>Server には SSH 設定の別名を指定できます。DBDock のトンネルは ProxyJump に未対応のため、最後のホストに直接接続してください。</p>'''),
('SSH ホスト設定', '''<p>「ファイル → SSH ホスト」（⇧⌘H）で ~/.ssh/config を管理します。ホストの追加・削除、HostName、User、Port、IdentityFile、ProxyJump の編集、エージェントや鍵によるログインテストができます。ターミナルまたは iTerm2 を選び「接続」を押すと、保存済みホストを OpenSSH で開きます。変更は先に保存してください。</p><p>その他の設定、コメント、インデントは保持されます。ファイル直接編集では Host *、Match なども扱えます。保存前に日時付き config.dbdock-*.bak を作成します。ホスト横の数字は使用中の DBDock 接続数です。</p>'''),
('SQL データベース', '''<h3>クイック切替</h3><p>⌘K で保存済みの接続、利用可能なデータベースやスキーマ、サイドバーで選んでいるスキーマのテーブルを検索できます。選択した項目をお気に入りに追加できます。「最近開いた項目」から以前の項目を再度開けます。お気に入りと最近開いた項目は端末に保存されます。MySQL または PostgreSQL のデータベースを選ぶと、独立したセッションを開くか再利用します。</p><h3>参照とクエリ</h3><p>データベースまたはスキーマを選んでテーブルを開きます。データ画面では初期設定で 1 ページに 5 行を読み込み、行数を変更できます。WHERE フィルター、列名補完、並べ替えにも対応します。構造画面には列、型、既定値、主キーを表示します。</p><p>SQL エディターでは ⌘↵ で選択範囲またはカーソル位置にある文全体、⇧⌘↵ でスクリプト全体を実行します。複数文とテーブル・列の補完に対応します。ツールバーから SQL ファイルを保存・読込できます。「クエリ履歴」から今回の実行で送信した SQL を検索、プレビュー、読み込みできます。履歴は接続とセッション開始時のデータベースごとに保持され、アプリ終了時に消去されます。⌃1–9 は上部タブ、⌘1–9 はデータベースタブを切り替え、修飾キーを押すと番号が表示されます。⌥⌘←/→ と ⌃⇧Tab / ⌃Tab で順に切り替えられます。MySQL と PostgreSQL のクエリは中止できますが、SQLite と D1 はできません。SQL エディターは 1 接続を使用し、USE、SET、トランザクションはそのセッションに適用されます。MySQL と PostgreSQL のテーブル表示は別の接続を使用し、コミット済みのデータを表示します。エディターのセッション設定や一時テーブルは共有されません。</p><h3>SQL 補完</h3><p>FROM または JOIN の後にスペースを入力すると、テーブル、ビュー、CTE が候補になります。スキーマ未指定の名前は、SET search_path や USE を反映したエディター接続の検索パスまたは現在のデータベースで解決されます。schema. を入力すると別のスキーマのテーブルが、エイリアスの後にドットを入力すると CTE やサブクエリの出力を含む列が表示されます。式にエイリアスを付けると外側のクエリから参照できます。WHERE や UPDATE … SET の後はクエリのスコープと既知の列型に応じて候補が表示されます。Tab で確定します。</p><p>JOIN … ON の後にスペースを入力すると、テーブル間の外部キーに基づく結合条件が候補になります。複合外部キーではすべての列の組み合わせが挿入されます。PostgreSQL と MySQL の ENUM 列は、比較、IN リスト、UPDATE … SET の代入で定義済みの値を補完できます。</p><h3>データ編集</h3><p>主キーを持つテーブルでは、ダブルクリックによる編集、行の追加・削除、NULL の設定ができます。⌘S でコミットし、SQL プレビューで実行内容を確認できます。すべて単一トランザクションで実行し、UPDATE または DELETE がちょうど 1 行に一致しなければ全体をロールバックします。</p><h3>D1 と互換サービス</h3><p>D1 はアカウント ID、データベース ID、D1 Edit 権限の API トークンを使い、Cloudflare REST API 経由で接続します。グリッド編集は単一のアトミックリクエストでコミットします。StarRocks と Doris は MySQL の種類を選びます。</p><h3>フィルター、エクスポート、保護</h3><p>フィルターでは複数の列の条件を AND または OR で組み合わせられます。インデックスと外部キーは閲覧専用です。結果バーから現在の結果を CSV または JSON でエクスポートできます。JSON は列の順序、重複した列名、NULL を保持します。CSV では表計算ソフトが数式として扱う可能性のある文字列に接頭辞を付けます。</p><p>本番 SQL 接続でも通常の読み取りクエリはそのまま実行できます。書き込みやロックを行う SQL、影響が不明な SQL、テーブル変更のコミットは確認が必要です。接続設定で確認を有効にするか、閲覧のみに切り替えられます。閲覧のみでは SQL の実行とコミットが無効になります。保護された接続では視覚フィルターを使い、設定変更後は再接続してください。行の更新や削除時に元の行を照合し、競合があれば変更をまとめてロールバックします。「変更を破棄して再読み込み」で最新の値を確認できます。</p><h3>構造の編集とデータファイル</h3><p>スキーマを選び「テーブルを作成」を押します。列名、型、既定値、主キーを指定し、SQL をプレビューして適用します。既存のテーブルでは「構造 → 構造を編集」で列の追加、名前変更、削除ができます。列の削除は再確認が必要です。PostgreSQL は型と NULL 制約の変更にも対応し、PostgreSQL と MySQL は既定値を変更できます。</p><p>データタブから CSV または JSON を読み込み、プレビューで列を対応付けます。インポートは行を追加し、エラー時は全件を取り消します。CSV には UTF-8 のヘッダーが必要です。引用符のない空欄は NULL、引用符付きの空欄は空文字列になります。JSON はオブジェクトの配列か DBDock の columns/rows 形式に対応します。上限は 5 MiB、5,000 行で、D1 は生成される SQL が 90 KB 以内です。</p><p>データタブではテーブルまたはビュー全体を出力できます。フィルターと未確定の変更は適用されません。D1 は最大 5,000 行です。バイナリ値は 0x で始まる 16 進表記です。再インポートには JSON を推奨します。</p>'''),
('Redis', '''<p>SCAN とパターンでキーを参照し、「さらに読み込む」で続行します。キーを選択すると string、hash、list、set、zset、stream のプレビュー、TTL、サイズを表示し、JSON 文字列は整形します。</p><p>データベースのメニューまたは SELECT でデータベースを切り替えます。下部のコンソールでコマンドを実行し、↑ / ↓ で履歴を参照できます。キーの削除前に確認します。</p>'''),
('MongoDB', '''<p>ホストとポート、またはホスト欄の mongodb:// / mongodb+srv:// URI で接続します。オプションには authSource、tls などを指定できます。SSH ではホストとポートを別々に入力してください。</p><h3>コレクション</h3><p>コレクションを選び、緩やかな構文で filter、sort、projection を入力できます。ObjectId と ISODate に対応します。テーブルと JSON を切り替え、ドキュメントをダブルクリックして Extended JSON を編集、または挿入・削除できます。既存ドキュメントの _id は変更できません。インデックスも表示できます。</p><h3>シェル</h3><p>⌘↵ で現在行または選択範囲を実行します。find、aggregate、countDocuments、distinct、挿入、更新、削除、db.runCommand、show dbs、show collections、use に対応します。</p>'''),
('Vim モードと外観', '''<p>「設定」（⌘,）でライト、ダーク、システムに合わせるを選択できます。言語はシステム、英語、簡体字中国語、繁体字中国語、日本語から選べます。Vim モードは SQL、Mongo シェル、ドキュメント、SSH 設定の各エディターに適用されます。</p><p>Esc で挿入モードを終了し、補完候補を閉じます。:w はドキュメントと設定では保存、SQL とシェルでは実行します。エディター内の Esc はダイアログを閉じません。</p>'''),
('キーボードショートカット', ''),
('データの保存先', '''<p>接続とグループ: <code>~/Library/Application Support/xyz.phpz.app.dbdock/</code>。パスワード、API トークン、SSH パスフレーズ: macOS キーチェーンの <code>xyz.phpz.app.dbdock</code> サービス。SSH ホスト: <code>~/.ssh/config</code>。画面設定はアプリ内に保存します。</p><p>指定したデータベースと SSH サーバー以外には接続しません。D1 では Cloudflare API にも接続します。</p>'''),
('トラブルシューティング', '''<h3>キーチェーンへのアクセス確認が繰り返される</h3><p>更新後の初回アクセス時、資格情報を新しい項目にコピーするため、旧項目へのアクセス許可を求められる場合があります。旧項目は復旧用に残り、以降は更新されません。同じ署名 ID でインストールしたアプリを使用してください。署名 ID の変更や紛失後は再度許可が必要な場合があります。</p><h3>インポート後にパスワード認証が失敗する</h3><p>TablePlus と DBeaver はパスワードを共有しません。接続を編集して入力してください。</p><h3>SSH ホスト鍵が拒否される</h3><p>ホスト鍵の信頼性を確認し、初回は OpenSSH で検証してください。サーバー再構築などで鍵が変わった場合は確認後に ssh-keygen -R host で古い記録を削除し、OpenSSH で新しい鍵を検証します。</p><h3>MySQL 互換サービスに接続できない</h3><p>ポートとユーザーの接続元権限を確認してください。StarRocks / Doris は通常 9030 を使います。</p><h3>テーブルが読み取り専用</h3><p>グリッド編集には主キーが必要です。ビューは常に読み取り専用です。SQL エディターを使用してください。</p>''')]
}
keys = ['start','connections','import','ssh','ssh-hosts','sql','redis','mongodb','vim','shortcuts','data','trouble']
labels = {'zh-CN': ['DBDock 帮助','搜索帮助','没有匹配内容。','MySQL、PostgreSQL、SQLite、Redis、MongoDB 和 Cloudflare D1，内置 SSH。'], 'zh-TW':['DBDock 說明','搜尋說明','沒有符合的內容。','MySQL、PostgreSQL、SQLite、Redis、MongoDB 和 Cloudflare D1，內建 SSH。'], 'ja':['DBDock ヘルプ','ヘルプを検索','一致する内容はありません。','MySQL、PostgreSQL、SQLite、Redis、MongoDB、Cloudflare D1 に対応。SSH を内蔵。']}
translations = {}
for lang, sections in content.items():
 assert len(sections)==len(keys)
 sections[9] = (sections[9][0], render_shortcuts(lang))
 translations[lang] = {'labels':labels[lang], 'sections':dict(zip(keys, ({'title':title,'html':body} for title,body in sections)))}
 Path(f'public/help.{lang}.json').write_text(json.dumps(translations[lang], ensure_ascii=False, indent=2)+'\n')
# A classic script also works when help.html is opened directly with file://.
Path('public/help.translations.js').write_text('window.DBDOCK_HELP_TRANSLATIONS = '+json.dumps(translations, ensure_ascii=False, indent=2)+';\n')

# Keep the English source and translated tables generated from the same rows.
help_path = Path('public/help.html')
html = help_path.read_text()
pattern = r'(<section id="shortcuts"[^>]*>\s*<h2>.*?</h2>).*?(\s*</section>)'
html, count = re.subn(pattern, lambda match: match.group(1) + '\n    ' + render_shortcuts('en') + match.group(2), html, flags=re.S)
assert count == 1, "English shortcut section not found"
help_path.write_text(html)
